package org.eclipse.rdf4j.workbench.proxy.config;

import jakarta.servlet.ServletException;

/** The Workbench policy ({@code workbench.properties}) could not be read or is invalid. */
public final class InvalidWorkbenchPolicyException extends ServletException {

	private static final long serialVersionUID = 1L;

	private final String problem;

	InvalidWorkbenchPolicyException(Throwable cause) {
		super("Unable to load valid Workbench policy (workbench.properties): " + problemOf(cause), cause);
		this.problem = problemOf(cause);
	}

	/** @return what is wrong with the policy, as the validation reported it */
	public String getProblem() {
		return problem;
	}

	private static String problemOf(Throwable cause) {
		String message = cause.getMessage();
		return message == null || message.isBlank() ? cause.getClass().getSimpleName() : message;
	}
}
